const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n);
const statusClass=s=>s==='Próximo ingreso'?'Próximo':s==='Visita agendada'?'Disponible':s;
const pages={overview:'Buen día, Valentín',vehicles:'Gestión de vehículos',leads:'Consultas recibidas',tradeins:'Tasaciones de usados',finance:'Solicitudes de financiación',analytics:'Estadísticas',settings:'Configuración'};
function go(page){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===page));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.querySelector('#pageTitle').textContent=pages[page];document.querySelector('#breadcrumb').textContent=`Panel / ${pages[page]}`;document.querySelector('#sidebar').classList.remove('open');window.scrollTo(0,0)}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
function renderVehicles(list=vehicles){document.querySelector('#vehicleTable').innerHTML=list.map(v=>`<tr><td><div class="vehicle-cell"><img src="${v.image}" alt=""><div><b>${v.brand} ${v.model}</b><small>ID VZ-${String(v.id).padStart(4,'0')} · Publicado</small></div></div></td><td><strong>${money(v.price)}</strong></td><td>${v.year} · ${v.km}</td><td><span class="status ${statusClass(v.status)}">${v.status}</span></td><td>${v.views}</td><td><strong>${v.leads}</strong></td><td><button class="actions" data-vehicle="${v.id}" aria-label="Acciones">•••</button></td></tr>`).join('')}
function renderLeads(list=leads){document.querySelector('#leadTable').innerHTML=list.map((l,i)=>`<tr><td><div class="vehicle-cell"><span class="avatar">${l.initials}</span><div><b>${l.name}</b><small>${l.phone}</small></div></div></td><td>${l.car}</td><td>${l.channel}</td><td>${l.date}</td><td><span class="status ${statusClass(l.status)}">${l.status}</span></td><td>${l.owner}</td><td><button class="actions" data-lead="${i}">→</button></td></tr>`).join('')}
function renderTrades(){document.querySelector('#tradeGrid').innerHTML=tradeins.map((t,i)=>`<article><div class="trade-head"><div class="vehicle-cell"><span class="avatar">${t.initials}</span><div><b>${t.name}</b><small>Solicitud desde la web</small></div></div><time>${t.date}</time></div><div class="trade-car"><strong>${t.car}</strong><small>${t.year} · ${t.km}</small><b>A tasar</b></div><div class="card-actions"><button class="outline" data-trade="${i}">Ver datos</button><button class="primary" data-toast="Tasación iniciada">Iniciar tasación</button></div></article>`).join('')}
function renderFinance(){document.querySelector('#financeTable').innerHTML=finances.map((f,i)=>`<tr><td><strong>${f.name}</strong></td><td>${f.car}</td><td><strong>${money(f.value)}</strong><br><small>Anticipo ${money(f.deposit)}</small></td><td>${f.term} cuotas</td><td>${f.date}</td><td><span class="status ${statusClass(f.status)}">${f.status}</span></td><td><button class="actions" data-finance="${i}">→</button></td></tr>`).join('')}
document.querySelector('#recentLeads').innerHTML=leads.slice(0,4).map(l=>`<div class="lead-row"><span class="avatar">${l.initials}</span><div><b>${l.name}</b><small>${l.car} · ${l.channel}</small></div><time>${l.date}</time></div>`).join('');
document.querySelector('#ranking').innerHTML=vehicles.slice().sort((a,b)=>b.views-a.views).slice(0,4).map((v,i)=>`<div class="rank-row"><span>0${i+1}</span><div><b>${v.brand} ${v.model}</b><small>${v.leads} consultas generadas</small></div><strong>${v.views} vistas</strong></div>`).join('');
renderVehicles();renderLeads();renderTrades();renderFinance();
const toastEl=document.querySelector('#toast');function toast(message){toastEl.textContent=message;toastEl.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2300)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-toast]');if(t)toast(t.dataset.toast)});
const carModal=document.querySelector('#carModal'),detailModal=document.querySelector('#detailModal');document.querySelectorAll('[data-new-car]').forEach(b=>b.onclick=()=>carModal.showModal());document.querySelectorAll('.modal-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelector('[data-close-modal]').onclick=()=>carModal.close();
document.querySelector('#carForm').onsubmit=e=>{e.preventDefault();carModal.close();toast('Vehículo publicado correctamente · Demo')};
document.querySelector('#vehicleTable').onclick=e=>{const b=e.target.closest('[data-vehicle]');if(!b)return;const v=vehicles.find(x=>x.id===+b.dataset.vehicle);showDetail(`<span>FICHA DE INVENTARIO</span><h2>${v.brand} ${v.model}</h2><p>ID VZ-${String(v.id).padStart(4,'0')} · Publicado en el sitio</p><div class="detail-info"><span><b>${money(v.price)}</b>Precio publicado</span><span><b>${v.status}</b>Estado actual</span><span><b>${v.views}</b>Visitas</span><span><b>${v.leads}</b>Consultas</span></div><div class="card-actions"><button class="outline" data-toast="Editor del vehículo abierto">Editar publicación</button><button class="primary" data-toast="Estado actualizado">Cambiar estado</button></div>`)};
document.querySelector('#leadTable').onclick=e=>{const b=e.target.closest('[data-lead]');if(!b)return;const l=leads[+b.dataset.lead];showDetail(`<span>DETALLE DE CONSULTA</span><h2>${l.name}</h2><p>${l.car} · ${l.channel}</p><div class="detail-info"><span><b>${l.phone}</b>Teléfono</span><span><b>${l.date}</b>Recibida</span><span><b>${l.status}</b>Estado</span><span><b>${l.owner}</b>Responsable</span></div><div class="card-actions"><button class="outline" data-toast="Llamada registrada">Registrar llamada</button><button class="primary" data-toast="Abriendo conversación de WhatsApp">Responder por WhatsApp</button></div>`)};
document.querySelector('#tradeGrid').onclick=e=>{const b=e.target.closest('[data-trade]');if(!b)return;const t=tradeins[+b.dataset.trade];showDetail(`<span>SOLICITUD DE TASACIÓN</span><h2>${t.car}</h2><p>Enviado por ${t.name} · ${t.date}</p><div class="detail-info"><span><b>${t.year}</b>Año</span><span><b>${t.km}</b>Kilometraje</span><span><b>${t.status}</b>Estado</span><span><b>6 fotos</b>Documentación</span></div><div class="card-actions"><button class="outline" data-toast="Solicitud marcada para revisión">Pedir más datos</button><button class="primary" data-toast="Tasación preliminar guardada">Cargar valor estimado</button></div>`)};
document.querySelector('#financeTable').onclick=e=>{const b=e.target.closest('[data-finance]');if(!b)return;const f=finances[+b.dataset.finance];showDetail(`<span>PROPUESTA DE FINANCIACIÓN</span><h2>${f.name}</h2><p>${f.car} · ${f.term} cuotas</p><div class="detail-info"><span><b>${money(f.value)}</b>Valor del vehículo</span><span><b>${money(f.deposit)}</b>Anticipo</span><span><b>${money(Math.round((f.value-f.deposit)*1.45/f.term))}</b>Cuota estimada</span><span><b>${f.status}</b>Estado</span></div><div class="card-actions"><button class="outline" data-toast="PDF de propuesta generado">Generar propuesta</button><button class="primary" data-toast="Cliente contactado">Contactar cliente</button></div>`)};
function showDetail(html){document.querySelector('#detailContent').innerHTML=`<div class="detail-body">${html}</div>`;detailModal.showModal()}
function filterVehicles(){const q=document.querySelector('#vehicleSearch').value.toLowerCase(),status=document.querySelector('#vehicleStatus').value,sort=document.querySelector('#vehicleSort').value;let list=vehicles.filter(v=>`${v.brand} ${v.model} ${v.year}`.toLowerCase().includes(q)&&(status==='all'||v.status===status));if(sort==='price')list.sort((a,b)=>b.price-a.price);if(sort==='views')list.sort((a,b)=>b.views-a.views);renderVehicles(list)}
function filterLeads(){const q=document.querySelector('#leadSearch').value.toLowerCase(),status=document.querySelector('#leadStatus').value,channel=document.querySelector('#leadChannel').value;renderLeads(leads.filter(l=>`${l.name} ${l.car}`.toLowerCase().includes(q)&&(status==='all'||l.status===status)&&(channel==='all'||l.channel===channel)))}
document.querySelector('#vehicleSearch').oninput=filterVehicles;document.querySelector('#vehicleStatus').onchange=filterVehicles;document.querySelector('#vehicleSort').onchange=()=>{filterVehicles();toast('Inventario ordenado')};document.querySelector('#leadSearch').oninput=filterLeads;document.querySelector('#leadStatus').onchange=filterLeads;document.querySelector('#leadChannel').onchange=filterLeads;
document.querySelector('#globalSearch').onkeydown=e=>{if(e.key==='Enter'){go('vehicles');document.querySelector('#vehicleSearch').value=e.target.value;document.querySelector('#vehicleSearch').dispatchEvent(new Event('input'))}};
document.querySelectorAll('[data-page-num]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-page-num]').forEach(x=>x.classList.toggle('active',x===b));toast(`Página ${b.dataset.pageNum} del inventario · Demo`)});document.querySelector('[data-next-page]').onclick=()=>{const current=document.querySelector('[data-page-num].active'),next=current.nextElementSibling?.dataset.pageNum;if(next)document.querySelector(`[data-page-num="${next}"]`).click();else toast('Ya estás en la última página')};
document.querySelectorAll('.settings-nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.settings-nav button').forEach(x=>x.classList.toggle('active',x===b));toast(`${b.textContent}: sección de demostración`)});
document.querySelector('#notifications').onclick=()=>toast('Tenés 8 consultas nuevas y 2 tasaciones pendientes');document.querySelector('#saveSettings').onclick=()=>toast('Configuración guardada correctamente · Demo');document.querySelector('#settingsForm').onsubmit=e=>e.preventDefault();document.querySelector('#mobileMenu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');
